"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[[4,7,10],[9,5,7],[7,11,3]],[[7,3,9],[7,10,6],[4,7,12]],[[11,6,7],[3,7,8],[10,5,7]],[[2,12,7],[11,7,4],[7,6,9]],[[7,8,5],[6,9,7],[12,7,2]],[[10,7,3],[7,2,11],[5,8,7]]];
let variant=OrionProgress.variant('ph'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,selected=-1,tested=new Set(),solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s];}
function kind(n){return n<7?'acid':n>7?'base':'neutral';}
function target(){return ['acid','neutral','base'][stage];}
function category(k){return k==='acid'?t('acidic','酸性'):k==='base'?t('alkaline','鹼性'):t('neutral','中性');}
function testSample(i){if(solved||!Number.isInteger(i)||i<0||i>2)return;selected=i;tested.add(i);state='ready';render();}
function resetTrial(){selected=-1;tested=new Set();solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('ph')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(tested.size<3||selected<0)state='incomplete';else if(kind(challenge()[selected])!==target())state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('indicator');}render();if(solved&&stage<2)$('next').focus();}
function drawing(){return '<div class="samples">'+challenge().map((n,i)=>{const seen=tested.has(i),color=!seen?'#abc7d0':n<7?'#efb86b':n>7?'#b39de4':'#85d7ac';return `<button data-sample="${i}" aria-pressed="${selected===i}" ${solved?'disabled':''} aria-label="${t('Test sample ','測試樣本 ')+String.fromCharCode(65+i)}"><svg viewBox="0 0 90 145" aria-hidden="true"><path d="M28 12H62V44L78 72V125Q78 138 66 138H24Q12 138 12 125V72L28 44Z" fill="#112d37" stroke="#c1d2d2" stroke-width="3"/><path d="M16 83H74V124Q74 134 64 134H26Q16 134 16 124Z" fill="${color}" opacity=".8"/><path d="M34 20V58L22 78" fill="none" stroke="#fff8" stroke-width="4"/></svg><b>${String.fromCharCode(65+i)}</b><span>${seen?'pH '+n:t('Untested','未測試')}</span><small>${seen?category(kind(n)):t('Tap to test','點選測試')}</small></button>`;}).join('')+'</div>';}
function hints(){return[t('Test all three samples. Tap a tested sample again to select it for the lantern.','測試三個樣本，再點選已測試的樣本供燈籠使用。'),t('In this 25 °C model, below pH 7 is acidic, pH 7 is neutral, and above 7 is alkaline.','在這個 25 °C 模型中，pH 低於 7 是酸性，7 是中性，高於 7 是鹼性。'),t('Choose sample '+String.fromCharCode(65+challenge().findIndex(n=>kind(n)===target()))+' for this lantern.','這盞燈籠需要樣本 '+String.fromCharCode(65+challenge().findIndex(n=>kind(n)===target()))+'。')];}
function render(){const complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Indicator Lantern Lab · Orion','指示燈籠實驗室 · Orion');$('stageTitle').textContent=t(`Lantern ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 盞燈 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Lab seals · ${p} / 3`,`實驗室封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();$('goal').textContent=t('Find the '+category(target())+' sample for this lantern.','為這盞燈籠找出'+category(target())+'樣本。');$('reading').textContent=selected<0?t('No sample selected.','尚未選擇樣本。'):t('Selected: '+String.fromCharCode(65+selected)+' · pH '+challenge()[selected],'已選：'+String.fromCharCode(65+selected)+' · pH '+challenge()[selected]);$('reference').textContent=t('Samples tested: '+tested.size+' / 3','已測試樣本：'+tested.size+' / 3');const messages={ready:['Test the vials, compare readings, then check your chosen sample.','測試小瓶、比較讀數，再檢查你選的樣本。'],incomplete:['Test all three samples before choosing.','選擇前，先測試全部三個樣本。'],wrong:['This sample has a different property. Compare the readings and try another.','這個樣本的性質不同。比較讀數，再試另一個。'],success:['The lantern recognises the sample. Another seal opens!','燈籠辨認了樣本，又一道封印打開！']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('indicator')?t('Indicator Sigil saved in your collection.','辨色符印已存入收藏。'):'';}
$('diagram').onclick=e=>{const b=e.target.closest('button[data-sample]');if(b){const i=Number(b.dataset.sample);testSample(i);$('diagram').querySelector('[data-sample="'+i+'"]').focus();}};
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('ph',variant);observedVariant=OrionProgress.variant('ph');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('indicator');render();};function syncProgress(){const v=OrionProgress.variant('ph'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('indicator')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
